/**
 * Evalúa una fórmula de estilo Excel guardando el resultado en la memoria.
 * @param {string} formula El texto ingresado (ej: "=SUMA(A1:A3)" o "=A1-B1").
 * @returns {number|null} El valor calculado, o null si es inválido.
 */
function calcularValorFormula(formula) {
    if (!formula || !formula.startsWith('=')) return null;

    let cleanFormula = formula.substring(1).trim();
    let result = 0;

    // --- Manejo de SUMA ---
    const sumMatch = cleanFormula.match(/^SUMA\((.*)\)$/i);
    if (sumMatch) {
        const content = sumMatch[1].trim();
        let valuesToSum = [];

        // Detectar si es un rango (e.g., A1:A3) o una lista separada por ;
        const rangeMatch = content.match(/([A-Z]+,[0-9]+):?([A-Z]+,[0-9]+)/);
        if (rangeMatch) {
            // Rango de celdas (ej: A1 a A3, o B2 a C3) - Simplificamos asumiendo columna y fila inicial/final.
            const startCoords = rangeMatch[1].split(',').map(s => s.trim());
            const endCoords = rangeMatch[2].split(',').map(s => s.trim());

            if (startCoords.length !== 2 || endCoords.length !== 2) return null;

            const startColChar = startCoords[0];
            const startRowNum = parseInt(startCoords[1]);
            const endColChar = endCoords[0];
            const endRowNum = parseInt(endCoords[1]);

            // Iterar sobre todas las combinaciones de filas y columnas en el rango
            for (let r = startRowNum; r <= endRowNum; r++) {
                for (let cCode = getColIndex(startColChar, endColChar); cCode <= getColIndex(endColChar, startColChar); cCode++) {
                    const colChar = indexToCharCode(cCode);
                    valuesToSum.push(`${colChar}, ${r}`);
                }
            }

        } else {
            // Lista de celdas separadas por ; (e.g., A1;B2;C3)
            const cellsList = content.split(';').map(s => s.trim());
            cellsList.forEach(cellRef => {
                if (isValidCellReference(cellRef)) {
                    valuesToSum.push(cellRef);
                }
            });
        }

        let total = 0;
        for (const key of valuesToSum) {
            const value = parseFloat(estado.cells[key]) || 0;
            total += value;
        }
        return total;
    }

    // --- Manejo de Operaciones Aritméticas Simples (A1-B1, A1*B1, etc.) ---
    try {
        let expression = cleanFormula.replace(/([A-Z]+,[0-9]+)/g, match => {
            const key = match; // Key format: "Col, Row"
            const value = parseFloat(estado.cells[key]) || 0;
            return value;
        });

        // Usar eval para calcular la expresión matemática resultante de las referencias a celdas
        result = eval(expression);
        return isNaN(result) ? null : result;
    } catch (e) {
        console.error("Error evaluating formula:", e);
        return null;
    }
}

/**
 * Convierte un carácter de columna ('A', 'B'...) a su índice numérico (1, 2...).
 */
function getColIndex(startChar, endChar) {
    let startCode = charToCode(startChar);
    let endCode = charToCode(endChar);

    if (startCode > endCode) return endCode;
    if (startCode < endCode) return startCode;
    return startCode; 
}

/**
 * Convierte un índice numérico (0, 1, 2...) de vuelta a su carácter ('A', 'B', 'C'...).
 */
function indexToCharCode(index) {
    if (index < 0) return null;
    return String.fromCharCode('A'.charCodeAt(0) + index);
}

/**
 * Convierte un carácter de columna a su código ASCII numérico.
 */
function charToCode(char) {
    const code = char.toUpperCase().charCodeAt(0);
    if (code >= 'A'.charCodeAt(0) && code <= 'Z'.charCodeAt(0)) {
        return code - 'A'.charCodeAt(0);
    }
    return null;
}

/**
 * Verifica si la referencia de celda es válida (ej: A1, B5).
 */
function isValidCellReference(ref) {
    const match = ref.match(/^([A-Z]+), \s*(\d+)$/i);
    return !!match;
}

/**
 * Helpers para el rango SUMA (simplicado para este contexto). 
 * Nota: Esto es una simplificación y asume que las referencias son de la forma Col, Row.
 */
function getColIndex(startChar, endChar) {
    return Math.min(charToCode(startChar), charToCode(endChar));
}

// Helper para calcular el máximo índice en un rango (ej: si es A1:C3, necesitamos 0 a 2).
function getColIndex(startChar, endChar) {
    const start = charToCode(startChar);
    const end = charToCode(endChar);
    return Math.max(start, end); // Devolvemos el máximo índice para iterar correctamente si no es un rango simple A:C
}

// Helper de columna (más robusto)
function getColIndex(startChar, endChar) {
    const startCode = charToCode(startChar);
    const endCode = charToCode(endChar);
    return Math.min(startCode, endCode);
}

