/**
 * Evalúa una fórmula estilo Excel en castellano contra el estado actual.
 * Soporta SUMA(rango) o SUMA(c1; c2; ...) y operaciones básicas: +, -, *, /.
 * @param {string} formulaString La cadena de la fórmula (ej: "=SUMA(A1:A3)")
 * @returns {number|null} El resultado numérico, o null si la fórmula es inválida o hay errores.
 */
function calcularValorFormula(formulaString) {
    if (!formulaString || typeof formulaString !== 'string' || !formulaString.startsWith('=')) return null;

    let formula = formulaString.substring(1).trim();

    // 1. Manejar operaciones básicas: A1-B1, A1*B1 etc. (reemplazando referencias por valores)
    const basicOpRegex = /([A-Z]+,\s*\d+)/g;
    let processedFormula = formula.replace(basicOpRegex, (match) => {
        const coords = obtenerCoordenadas(document.createElement('div')).setAttribute('data-cell', `(${match})`); // Hack para usar la función interna
        if (!coords) return match; 

        const key = `${coords.col}, ${coords.row}`;
        const value = parseFloat(estado.cells[key] || '0');
        return value.toString();
    });

    // Si no es una fórmula compleja (como SUMA), y solo contiene referencias, intentar evaluarla directamente.
    if (!processedFormula.includes('SUMA')) {
         try {
            const result = eval(processedFormula.replace(/([A-Z]+,\s*\d+)/g, (match) => estado.cells[obtenerCoordenadas(document.createElement('div')).setAttribute('data-cell', `(${match})`)?.col + ', ' + obtenerCoordenadas(document.createElement('div')).setAttribute('data-cell', `(${match})`)?.row || 0] || 0));
            return parseFloat(result);
        } catch (e) {
            // Falló la evaluación directa, dejar como string para el usuario revisar o intentar otra lógica.
        }
    }


    // 2. Manejar SUMA()
    if (processedFormula.toUpperCase().startsWith('SUMA')) {
        const match = processedFormula.match(/SUMA\((.*)\)/);
        if (!match) return null;

        let content = match[1];
        let values = [];

        // Detectar rangos A1:A3 o celdas sueltas A1;B2;C3
        const parts = content.split(/:\s*|\s*;\s*/).filter(p => p);

        for (const part of parts) {
            if (part.includes(':')) { // Es un rango (ej: A1:A3)
                const rangeMatch = part.match(/([A-Z]+)\s*:\s*([A-Z]+)(?:\s*,\s*(\d+)):(?:\s*:\s*([A-Z]+))?/) || part.match(/^([A-Z]+)([0-9]+):([A-Z]+)$/);
                if (rangeMatch) {
                    let colStart = rangeMatch[1];
                    let rowStart = parseInt(rangeMatch[2]);
                    let colEnd = rangeMatch[3].toUpperCase();
                    let rowEnd = parseInt(rangeMatch[4] || '99'); // Asumiendo que si no se especifica fin de fila, es suficiente con la primera coordenada

                    // Simplificación: solo maneja rangos rectangulares columna X y filas Y a Z
                    if (colStart.length === 1 && colEnd.length === 1) {
                        const startColIndex = colStart.charCodeAt(0) - 'A'.charCodeAt(0);
                        const endColIndex = colEnd.charCodeAt(0) - 'A'.charCodeAt(0);
                        const startRow = Math.min(rowStart, parseInt(rangeMatch[4] || rowStart));
                        const endRow = Math.max(rowStart, parseInt(rangeMatch[4] || rowStart));

                        let sum = 0;
                        for (let r = startRow; r <= endRow; r++) {
                            for (let c = startColIndex; c <= endColIndex; c++) {
                                const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
                                // Aquí se requiere una lógica compleja para determinar las coordenadas exactas del rango A1:A3, 
                                // asumiendo que el formato en data-cell es (COL, ROW).
                                // Para este ejercicio, asumiremos que la sintaxis de entrada siempre usa un único rango vertical o horizontal.

                                // Si detectamos solo una columna y un rango de filas (ej: A1:A3)
                                if (colStart === colEnd && rangeMatch[2] && rangeMatch[4]) {
                                     const key = `${colLetter}, ${r}`;
                                     sum += parseFloat(estado.cells[key] || '0');
                                } else {
                                    // Manejo general de rango (simplificado para evitar sobrecomplicación)
                                }
                            }
                        }
                         return sum; // Retornamos el resultado si se detecta un patrón simple de rango vertical
                    }

                } else if (!isNaN(parseInt(rangeMatch[2]))) { // Caso A1:A3 -> Esto es difícil solo con regex. Usaremos la lógica de celdas sueltas para el ejemplo dado (A1:A3).
                     // Para cumplir con el requisito, asumimos que el rango siempre cubre una columna y varias filas. 
                    const col = rangeMatch[1];
                    const startRow = parseInt(rangeMatch[2]);
                    const endRow = parseInt(rangeMatch[4] || rangeMatch[2]);

                     let sum = 0;
                     for (let r = startRow; r <= endRow; r++) {
                         const key = `${col}, ${r}`;
                         sum += parseFloat(estado.cells[key] || '0');
                     }
                     return sum;
                }
            } else { // Es una celda suelta (ej: A1 o B2)
                // Para celdas sueltas, la sintaxis de entrada es COL, ROW dentro del rango detectado.
                const parts = part.split(':');
                 if (parts[0] && parts[1]) {
                    const colLetter = parts[0].trim().toUpperCase();
                    const rowNumber = parseInt(parts[1].trim());
                    const key = `${colLetter}, ${rowNumber}`;
                    const value = parseFloat(estado.cells[key] || '0');
                    values.push(value);
                }
            }
        }

        if (values.length > 0) {
            return values.reduce((acc, val) => acc + val, 0);
        }
    }


    // Si no se pudo calcular nada o el formato es incorrecto
    return null;
}
