### FUNCION: actualizarCeldaEstado
```js
/**
 * Actualiza el estado interno de la celda basándose en su elemento DOM y nuevo valor.
 * @param {HTMLElement} element El elemento que ha cambiado.
 * @param {string} newValue El texto actual del elemento.
 * @returns {boolean} True si se pudo actualizar, False en caso contrario.
 */
function actualizarCeldaEstado(element, newValue) {
    const coords = obtenerCoordenadas(element);
    if (!coords) return false;

    // Formato de clave requerido: Columna, Espacio, Número (ej: "A, 1")
    const key = `${coords.col}, ${coords.row}`;
    let finalValue = newValue.trim();

    // Verificar si el valor ingresado es una fórmula
    if (finalValue.startsWith('=')) {
        try {
            // Intentar calcular el valor basado en el estado actual
            const calculatedValue = calcularValorFormula(finalValue);

            if (calculatedValue !== null) {
                // Si la fórmula se pudo resolver, guardamos solo el resultado numérico.
                finalValue = calculatedValue.toFixed(2).replace(/\.?0+$/, ''); // Formatear a string sin decimales innecesarios
            } else {
                // Si no se puede calcular (ej: referencia incorrecta), lo dejamos como fórmula para que el usuario lo revise o edite la referencia.
                finalValue = newValue; 
            }
        } catch (e) {
             console.error("Error al calcular fórmula:", e);
             // En caso de error, guardamos el valor literal ingresado.
             finalValue = newValue;
        }
    }

    // Actualizar estado con el valor final (calculado o literal)
    estado.cells[key] = finalValue;
    return true;
}
