```javascript
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
let estado = { 
    cells: {} // Key format: "ColumnLetter, RowNumber" (e.g., "A, 1")
};
const CLAVE = "app";

/**
 * Carga el estado desde localStorage.
 */
function cargar() { try { const s = localStorage.getItem(CLAVE); if (s) estado = JSON.parse(s); } catch (e) {} }

/**
 * Guarda el estado actual en localStorage.
 */
function guardar() { try { localStorage.setItem(CLAVE, JSON.stringify(estado)); } catch (e) {} }

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Extrae las coordenadas de una celda a partir de su atributo data-cell="(X, Y)".
 * @param {HTMLElement} element El elemento TD.
 * @returns {{col: string, row: number}|null} Las coordenadas o null si fallan.
 */
function obtenerCoordenadas(element) {
    const dataCell = element.getAttribute('data-cell');
    if (!dataCell) return null;

    // Regex para capturar Columna y Número de Fila (ej: A, 1)
    const match = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
    if (!match) return null;

    // Limpiar paréntesis y obtener la cadena "Col, Row"
    const coordsString = match[1].replace(/[()]/g, ''); 

    // Dividir por coma (puede haber espacios extra)
    const parts = coordsString.split(',').map(p => p.trim());

    if (parts.length !== 2 || isNaN(parseInt(parts[1]))) {
        return null;
    }

    return { col: parts[0], row: parseInt(parts[1]) };
}


/**
 * Evalúa una fórmula estilo Excel en castellano contra el estado actual.
 * Soporta SUMA(rango) o SUMA(c1; c2; ...) y operaciones básicas: +, -, *, /.
 * @param {string} formulaString La cadena de la fórmula (ej: "=SUMA(A1:A3)")
 * @returns {number|null} El resultado numérico, o null si la fórmula es inválida o hay errores.
 */
function calcularValorFormula(formulaString) {
    if (!formulaString || typeof formulaString !== 'string' || !formulaString.startsWith('=')) return null;

    let formula = formulaString.substring(1).trim();
    const getCoordFromMatch = (match) => {
        // Este truco es necesario porque obtenerCoordenadas necesita un elemento DOM, pero aquí solo tenemos la string del match.
        const tempElement = document.createElement('div');
        tempElement.setAttribute('data-cell', `(${match})`);
        return obtenerCoordenadas(tempElement);
    };

    // 1. Manejar operaciones básicas: A1-B1, A1*B1 etc. (reemplazando referencias por valores)
    let processedFormula = formula;
    const basicOpRegex = /([A-Z]+,\s*\d+)/g;
    processedFormula = processedFormula.replace(basicOpRegex, (match) => {
        const coords = getCoordFromMatch(match); 
        if (!coords) return match; 

        const key = `${coords.col}, ${coords.row}`;
        const value = parseFloat(estado.cells[key] || '0');
        return value.toString();
    });

    // Si la fórmula no contiene SUMA, intentar evaluar directamente (solo para operaciones básicas A1-B1 etc.)
    if (!processedFormula.includes('SUMA')) {
         try {
            const result = eval(processedFormula);
            return parseFloat(result);
        } catch (e) {
            // Falló la evaluación directa, devolver null o dejar el error para que el usuario lo revise.
        }
    }


    // 2. Manejar SUMA()
    if (processedFormula.toUpperCase().startsWith('SUMA')) {
        const match = processedFormula.match(/SUMA\((.*)\)/);
        if (!match) return null;

        let content = match[1];
        let values = [];

        // Dividir por rangos o separadores de celdas sueltas (semicolon)
        const parts = content.split(/:\s*|\s*;\s*/).filter(p => p);

        for (const part of parts) {
            if (part.includes(':')) { // Es un rango (ej: A1:A3)
                // Regex más robusta para capturar rangos verticales de columna única, como en el ejemplo A1:A3
                const rangeMatch = part.match(/^([A-Z]+)\s*:\s*([A-Z]+)(?:\s*,\s*(\d+)):(?:\s*:\s*([A-Z]+))?/i);

                if (rangeMatch) {
                    let colStart = rangeMatch[1].toUpperCase();
                    let rowStart = parseInt(rangeMatch[2]);
                    // Si se provee el final de la columna, pero no el final de fila, asumimos que es vertical. 
                    // Simplificamos asumiendo un rango A1:A3 (misma columna)
                    const colEnd = rangeMatch[3] ? rangeMatch[3].toUpperCase() : colStart;
                    let rowEnd = parseInt(rangeMatch[4]); // El final de fila

                     if (!isNaN(rowStart) && !isNaN(colStart.charCodeAt(0) - 'A'.charCodeAt(0)) && !isNaN(parseInt(colStart))) {
                         // Asumiendo un rango vertical A1:A3 (misma columna, filas incrementales)
                         let sum = 0;
                         for (let r = rowStart; r <= rowEnd || (!isNaN(rowEnd) && r > rowStart); r++) {
                             const key = `${colStart}, ${r}`;
                             sum += parseFloat(estado.cells[key] || '0');
                         }
                         return sum; // Devolver inmediatamente el resultado del rango si se detecta un patrón de columna única.
                     }
                }

            } else { // Celda suelta (ej: A1)
                const coords = getCoordFromMatch(part);
                if (coords) {
                    const key = `${coords.col}, ${coords.row}`;
                    values.push(parseFloat(estado.cells[key] || '0'));
                }
            }
        }

        // Si no se pudo calcular nada o el formato es incorrecto, devolver null
    }

    return null;
}


/**
 * Actualiza el estado interno de la celda basándose en su elemento DOM y nuevo valor.
 * @param {HTMLElement} element El elemento que ha cambiado.
 * @param {string} newValue El texto actual del elemento.
 * @returns {boolean} True si se pudo actualizar, False en caso contrario.
 */
function actualizarCeldaEstado(element, newValue) {
    const coords = obtenerCoordenadas(element);
    if (!coords) return false;

    // Formato de clave requerido: Columna, Espacio, Número (ej: "A, 1")
    const key = `${coords.col}, ${coords.row}`;
    let finalValue = newValue.trim();

    // Verificar si el valor ingresado es una fórmula
    if (finalValue.startsWith('=')) {
        try {
            // Intentar calcular el valor basado en el estado actual
            const calculatedValue = calcularValorFormula(finalValue);

            if (calculatedValue !== null) {
                // Si la fórmula se pudo resolver, guardamos solo el resultado numérico.
                finalValue = parseFloat(calculatedValue).toFixed(2).replace(/\.?0+$/, ''); // Formatear a string sin decimales innecesarios
            } else {
                // Si no se puede calcular (ej: referencia incorrecta), lo dejamos como fórmula para que el usuario lo revise o edite la referencia.
                finalValue = newValue; 
            }
        } catch (e) {
             console.error("Error al calcular fórmula:", e);
             // En caso de error, guardamos el valor literal ingresado.
             finalValue = newValue;
        }
    }

    // Actualizar estado con el valor final (calculado o literal)
    estado.cells[key] = finalValue;
    return true;
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
  const bodyRows = document.querySelectorAll('#spreadsheet-grid tbody tr');

  bodyRows.forEach(row => {
      // Iteramos sobre todos los hijos de las filas (los TD). 
      // El primer hijo es el th.row-header, por lo que empezamos en índice 1.
      const rowCells = Array.from(row.children);
      for (let i = 1; i < rowCells.length; i++) {
          const cellElement = rowCells[i];
          if (!cellElement) continue;

          // Extraer la clave de coordenadas del atributo data-cell="(X, Y)"
          const dataCell = cellElement.getAttribute('data-cell');
          if (!dataCell) continue;

          const coordsMatch = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
          if (!coordsMatch) continue;

          // Crear la clave de estado ("A, 1")
          const key = coordsMatch[1].replace(/[()]/g, ''); 

          // Obtener el valor del estado (o vacío si no existe)
          const cellValue = estado.cells[key] || '';

          // Actualizar el contenido visible del elemento DOM
          cellElement.textContent = cellValue;
      }
  });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const grid = document.getElementById('spreadsheet-grid');

    if (!grid) return;

    /**
     * Maneja el guardado de datos cuando el usuario deja de editar (focusout).
     */
    grid.addEventListener('focusout', function(event) {
        const target = event.target;
        // Solo procesar si es un TD editable
        if (!target || !target.hasAttribute('contenteditable') || !target.dataset.cell) return;

        const newValue = target.textContent;

        // 1. LÓGICA: Actualizar el estado interno
        actualizarCeldaEstado(target, newValue); 

        // 2. GUARDAR y DIBUJAR
        guardar();
        render();
    });

    /**
     * Maneja el guardado de datos cuando se presiona Enter dentro de una celda editable.
     */
    grid.addEventListener('keydown', function(event) {
        const target = event.target;

        // Solo procesar si es un TD editable y la tecla presionada fue Enter
        if (!target || !target.hasAttribute('contenteditable') || event.key !== 'Enter') return;

        // Prevenir el comportamiento por defecto del formulario (si lo hubiera)
        event.preventDefault(); 

        const newValue = target.textContent;

        // 1. LÓGICA: Actualizar el estado interno
        actualizarCeldaEstado(target, newValue); 

        // 2. GUARDAR y DIBUJAR
        guardar();
        render();
    });
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
