### FUNCION: calcularFormula
```javascript
/**
 * Evalúa una fórmula de hoja de cálculo simple. Soporta SUMA y operaciones aritméticas básicas (+, -, *, /).
 * @param {string} formula La cadena de la fórmula (debe empezar con '=').
 * @returns {number|null} El resultado calculado o null si falla.
 */
function calcularFormula(formula) {
    let cleanFormula = formula.trim();
    if (!cleanFormula || !cleanFormula.startsWith('=')) return null;

    // Quitar el signo igual inicial para el procesamiento interno
    let content = cleanFormula.substring(1); 

    try {
        // 1. Manejar SUMA()
        const sumMatch = content.match(/^SUMA\((.*)\)$/i);
        if (sumMatch) {
            const argsString = sumMatch[1]; // Contenido dentro de los paréntesis

            // Separar argumentos por punto y coma o comas, e ignorar espacios en blanco
            let argumentsList = argsString.split(/[,;]/).map(a => a.trim()).filter(a => a.length > 0);

            if (argumentsList.length === 0) return null;

            let totalSum = 0;
            for (const arg of argumentsList) {
                // Verificar si el argumento es un rango (ej: A1:A3) o una celda suelta (ej: B2)
                if (arg.includes(':')) {
                    // Manejo de rangos (simplificado para este ejercicio, asume columna única)
                    const rangeMatch = arg.match(/([A-Z]+):([A-Z]+)\s*:\s*(\d+):\s*(\d+)/i); 
                    if (!rangeMatch) {
                        // Si el rango no coincide con A1:A3, asumimos que es una simple concatenación de referencias.
                         let rangeRefs = arg.split(':').map(r => r.trim()).filter(r => r.length > 0);
                         for (const ref of rangeRefs) {
                             totalSum += getCellValue(ref);
                         }
                    } else {
                        // Si el rango está bien formado, sumamos celda por celda en la columna dada.
                        const col = rangeMatch[1].toUpperCase();
                        const startRow = parseInt(rangeMatch[3]);
                        const endRow = parseInt(rangeMatch[4]);

                        for (let r = startRow; r <= endRow; r++) {
                            totalSum += getCellValue(`${col}${r}`);
                        }
                    }
                } else {
                    // Celda suelta simple
                    totalSum += getCellValue(arg);
                }
            }
            return totalSum;
        }

        // 2. Manejar Operaciones Aritméticas Básicas (+, -, *, /)
        // Reemplazamos referencias de celda con sus valores numéricos antes de evaluar.
        let tempContent = content;
        // Regex: encuentra una o más letras seguidas por un espacio y uno o más dígitos (ej: A 1)
        tempContent = tempContent.replace(/([A-Z]+)\s*(\d+)/gi, (match, col, row) => {
            return getCellValue(`${col}${row}`) !== null ? `(${getCellValue(`${col}${row}`)})` : match;
        });

        // Evaluar la expresión matemática usando eval() en un entorno controlado.
        // Es crucial que los valores sean rodeados de paréntesis para evitar errores de operador.
        return eval(tempContent);

    } catch (e) {
        console.error("Error evaluating formula:", e);
        // Si falla, devolver el valor original o null
        return null; 
    }
}
