```javascript
// CONSTANTES GLOBALES Y ESTADO
const CLAVE = 'spreadsheet_state';
let estado = {
    cells: {}, // Almacena el valor de cada celda ("A, 1": "valor")
    colors: {}  // Almacena el color de fondo de cada celda ("A, 1": "#RRGGBB")
};

/**
 * Guarda el estado actual (valores y colores) en localStorage.
 */
function guardar() { 
    try { 
        estado.cells = state.cells || {};
        // Aseguramos que el mapa de colores esté incluido en el estado guardado
        if (!estado.colors) {
            estado.colors = {};
        }
        localStorage.setItem(CLAVE, JSON.stringify({ ...estado, colors: estado.colors })); 
    } catch (e) {} 
}

/**
 * Carga el estado desde localStorage.
 */
function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            const loadedState = JSON.parse(s);
            // Fusionar el estado cargado con la estructura inicial, asegurando que 'colors' exista
            estado = { ...estado, ...loadedState };
             // Aseguramos que el objeto de colores esté presente en caso de carga parcial o antigua
            if (typeof estado.colors === 'undefined') {
                estado.colors = {};
            }
        } else {
             // Inicializar colors si es la primera vez
             estado.colors = {};
        }
    } catch (e) {} 
}

/**
 * Obtiene las coordenadas de una celda dada su elemento DOM.
 * @param {HTMLElement} element - El elemento TD.
 * @returns {string|null} Coordenadas en formato "A, 1" o null si no es válido.
 */
function obtenerCoordenadas(element) {
    const dataCell = element.getAttribute('data-cell');
    if (!dataCell || !dataCell.includes(',')) return null;

    // Regex para capturar (X, Y) y luego limpiar los paréntesis
    const coordsMatch = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
    if (!coordsMatch) return null;

    return coordsMatch[1].replace(/[()]/g, ''); 
}

/**
 * Obtiene el valor de estado para una referencia de celda (ej: "A, 1").
 * @param {string} reference - La clave en formato "X, Y".
 * @returns {(number|string)} El valor almacenado o vacío.
 */
function getCellValue(reference) {
    return estado.cells[reference] || '';
}

/**
 * Calcula el resultado de una fórmula (ej: "=A1+B1").
 * @param {string} formula - La cadena que contiene la fórmula.
 * @returns {(number|null)} El resultado numérico o null si no es calculable.
 */
function calcularFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return null;
    }

    let expression = formula;
    // Reemplazar referencias de celda (ej: A1) por sus valores reales
    const regex = /([A-Z]\, [0-9]+)/g;
    expression = expression.replace(regex, (match) => {
        const key = match.replace(/\s/g, ''); // Eliminar espacios si los hubiera en las coordenadas
        let value = getCellValue(key);

        // Si el valor es un número o vacío, lo usamos directamente; si no, se trata como string para evitar NaN
        if (typeof value === 'number' || value === '') {
            return typeof value === 'number' ? value : 0;
        }
        return `"${value}"`; // Tratar textos como cadenas en la expresión de JS
    });

    try {
        // Evalúa la expresión matemática resultante
        const result = eval(expression);
        if (isNaN(result) || !isFinite(result)) return null;
        return Number(result.toFixed(2)); // Limitar a 2 decimales para consistencia
    } catch (e) {
        console.error("Error al evaluar la fórmula:", e);
        return null;
    }
}

/**
 * Actualiza el valor del estado y actualiza visualmente una celda.
 * @param {HTMLElement} element - El elemento TD a actualizar.
 * @param {(number|string)} newValue - El nuevo valor (ya calculado o escrito).
 */
function actualizarCeldaEstado(element, newValue) {
    const key = obtenerCoordenadas(element);
    if (!key) return;

    // 1. Actualizar el estado interno
    estado.cells[key] = newValue;

    // 2. Renderizar solo este elemento para reflejar los cambios de valor/fórmula
    renderSingleCell(element, key, newValue);
}


/**
 * Renderiza una única celda, aplicando formato y contenido desde el estado.
 * @param {HTMLElement} element - El elemento TD a actualizar.
 * @param {string} key - La clave de coordenadas "A, 1".
 * @param {(number|string)} cellValue - El valor actual en el estado.
 */
function renderSingleCell(element, key, cellValue) {
    // --- APLICAR COLOR DE FONDO (NUEVO) ---
    let color = estado.colors[key] || '#ffffff';
    element.style.backgroundColor = color;

    // Determinar el contenido a mostrar
    if (typeof cellValue === 'number' && !isNaN(cellValue)) {
        element.textContent = cellValue;
    } else if (typeof cellValue === 'string') {
        if (cellValue.startsWith('=')) {
             const calculatedResult = calcularFormula(cellValue);
             if (calculatedResult !== null) {
                 element.textContent = calculatedResult;
             } else {
                 // Si es una fórmula que no se puede calcular, mostrar la fórmula misma
                 element.textContent = cellValue; 
             }
        } else {
            // Valor normal o vacío
            element.textContent = cellValue;
        }
    } else {
         element.textContent = '';
    }
}


/**
 * Renderiza toda la hoja de cálculo a partir del estado.
 */
function render() {
  const bodyRows = document.querySelectorAll('#spreadsheet-grid tbody tr');

  bodyRows.forEach(row => {
      // Iteramos sobre todos los hijos de las filas (los TD). 
      const rowCells = Array.from(row.children);
      for (let i = 1; i < rowCells.length; i++) {
          const cellElement = rowCells[i];
          if (!cellElement) continue;

          // Extraer la clave de coordenadas del atributo data-cell="(X, Y)"
          const key = obtenerCoordenadas(cellElement);
          if (!key) continue;

          // Obtener el valor del estado (o vacío si no existe)
          let cellValue = getCellValue(key);

          renderSingleCell(cellElement, key, cellValue);
      }
  });
}


/**
 * Cambia el color de fondo de una celda específica.
 * @param {HTMLElement} element - El elemento TD afectado.
 * @param {string} key - La clave de coordenadas "A, 1".
 * @param {string} color - Código hexadecimal del color.
 */
function cambiarColorCelda(element, key, color) {
    // 1. Actualizar estado de colores
    if (!estado.colors) {
        estado.colors = {};
    }
    estado.colors[key] = color;

    // 2. Aplicar el estilo visualmente y actualizar el renderizado para que todos vean el cambio
    renderSingleCell(element, key, getCellValue(key)); // Esto aplica el color guardado/nuevo
    guardar();
}


/**
 * Conecta los manejadores de eventos a la interfaz de usuario.
 */
function conectar() {
    // 1. Manejo del input (Evento en el contenedor) - Reescrito para manejar el cambio y recalcular inmediatamente
    const spreadsheetGrid = document.getElementById('spreadsheet-grid');
    spreadsheetGrid.addEventListener('input', function (e) {
        if (!e.target.hasAttribute('contenteditable') || !e.target.closest('[data-cell]')) return;

        const element = e.target;
        const key = obtenerCoordenadas(element); 
        let newValue = element.textContent;

        // Actualizar el estado con lo que se está escribiendo en tiempo real
        estado.cells[key] = newValue; 

        // Recalcular fórmulas inmediatamente al escribir (y actualizar visualmente)
        const formulaResult = calcularFormula(newValue);
        if (formulaResult !== null && !isNaN(parseFloat(formulaResult))) {
            actualizarCeldaEstado(element, parseFloat(formulaResult));
        } else {
             // Si no es fórmula o falla el cálculo, actualizar con lo escrito.
             actualizarCeldaEstado(element, newValue);
        }

        guardar();
    });


    // 2. Manejo de foco perdido (blur) - Para forzar cálculos y guardar estado al terminar la edición
    spreadsheetGrid.addEventListener('blur', function(e) {
        if (!e.target.hasAttribute('contenteditable') || !e.target.closest('[data-cell]')) return;

        const element = e.target;
        const key = obtenerCoordenadas(element); 
        let newValue = element.textContent;

        // Actualizar el estado con el valor final del blur
        estado.cells[key] = newValue;

        // Forzar cálculo y actualización de estado
        const formulaResult = calcularFormula(newValue);
        if (formulaResult !== null && !isNaN(parseFloat(formulaResult))) {
            actualizarCeldaEstado(element, parseFloat(formulaResult));
        } else {
             // Si no es fórmula o falla, actualizar el valor.
             actualizarCeldaEstado(element, newValue);
        }

        guardar();
    }, true); // Usamos 'true' para capturar eventos de burbujeo en el contenedor principal


    // 3. Conectar Eventos del Color Picker (NUEVO)
    const colorPicker = document.getElementById('color-picker');
    const toggleButton = document.getElementById('toggle-color-picker');
    const colorSelector = document.getElementById('bg-color-selector');
    const applyButton = document.getElementById('apply-color');

    // Toggle visibility of the color picker
    toggleButton.addEventListener('click', function () {
        colorPicker.classList.toggle('hidden');
    });

    // Handle applying the color
    applyButton.addEventListener('click', function () {
        const selectedColor = colorSelector.value;
        let targetCell = document.activeElement;

        if (!targetCell || !targetCell.hasAttribute('data-cell')) {
            alert("Por favor, haz clic en una celda para cambiar su color.");
            return;
        }

        const key = obtenerCoordenadas(targetCell); 

        // Llamar a la función que maneja el estado y renderizado visual
        cambiarColorCelda(targetCell, key, selectedColor);

        // Ocultar el selector después de aplicar
        colorPicker.classList.add('hidden');
    });


    // Inicialización del color picker al cargar la página (si hay colores guardados)
    const initialColor = estado.colors['A, 1'] || '#ffffff';
    if(initialColor){
        colorSelector.value = initialColor;
    }

}

/**
 * Función de arranque principal que inicializa el estado y renderiza la vista.
 */
function arrancar() { 
    cargar(); // Cargar datos e historial
    conectar(); // Configurar eventos
    render();  // Dibujar la interfaz con los datos cargados
}
