### FUNCION: deleteColumn
```js
function deleteColumn(colLetter) {
    if (!confirm(`¿Estás seguro de que quieres eliminar la columna ${colLetter}? Esta acción es irreversible.`)) return;

    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    let cellsToDelete = [];

    // 1. Recopilar todas las coordenadas a borrar de estado.cells
    rows.forEach(row => {
        // Encontrar la celda con esta columna en la fila actual
        const cellSelector = `[data-cell^="(${colLetter},"]`;
        const targetCell = row.querySelector(cellSelector);

        if (targetCell) {
            const dataCell = targetCell.getAttribute('data-cell');
            const coordsMatch = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
            if (coordsMatch) {
                const key = coordsMatch[1].replace(/[()]/g, ''); 
                cellsToDelete.push(key);
            }
        }
    });

    // Borrar de estado.cells
    cellsToDelete.forEach(key => delete estado.cells[key]);

    // Actualizar el estado visual y los controles
    estado.selectedColumn = null;
    guardar();
    render();
    renderColumnControls(null); // Limpiar controles
}
