function clearColumn(colLetter) {
    let clearedCount = 0;
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');

    rows.forEach(row => {
        // Intentar encontrar la celda de esta columna en la fila actual
        const cellSelector = `[data-cell^="(${colLetter},"]`;
        const targetCell = row.querySelector(cellSelector);

        if (targetCell) {
            const dataCell = targetCell.getAttribute('data-cell');
            const coordsMatch = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
            if (coordsMatch) {
                const key = coordsMatch[1].replace(/[()]/g, ''); 
                // Borrar el valor de estado y limpiar la celda visualmente
                delete estado.cells[key];
                clearedCount++;
            }
        }
    });

    if (clearedCount > 0) {
        guardar();
        render();
    } else {
        console.warn(`No se encontraron celdas para limpiar en la columna ${colLetter}.`);
    }
}
