### FUNCION: deleteColumn
```javascript
/**
 * Elimina una columna de la hoja de cálculo, actualizando el estado y el DOM.
 * @param {string} colLetter La letra de la columna a eliminar (ej: "A").
 */
function deleteColumn(colLetter) {
    if (!colLetter || !/[A-Z]/.test(colLetter)) return false;

    const bodyRows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    let cellsDeletedCount = 0;

    // 1. Eliminar el estado de la columna (estado.cells)
    for (let r = 1; r <= 20; r++) {
        const key = `${colLetter}, ${r}`;
        if (estado.cells[key] !== undefined) {
            delete estado.cells[key];
            cellsDeletedCount++;
        }
    }

    // 2. Eliminar la columna del DOM: En el encabezado (<thead>)
    const headerThs = document.querySelectorAll('#spreadsheet-grid thead th');
    let colIndexToDelete = -1;
    for(let i = 0; i < headerThs.length; i++) {
        const currentTh = headerThs[i];
        // Saltar la esquina superior izquierda (índice 0)
        if (i > 0) {
            const letter = currentTh.textContent.trim();
            if (letter === colLetter) {
                colIndexToDelete = i;
                break;
            }
        }
    }

    if (colIndexToDelete !== -1) {
        headerThs[colIndexToDelete].remove();
    } else {
        console.warn(`Columna ${colLetter} no encontrada en el encabezado.`);
        return false;
    }


    // 3. Eliminar la columna de todas las filas (<tbody>)
    for (const row of bodyRows) {
        // Buscar el TD correspondiente a esta letra de columna
        const colIndex = Array.from(row.children).findIndex((child, index) => {
            // Empezamos en índice 1 para saltar el th.row-header
            if (index === 0) return false; 

            const cellElement = child;
            const dataCell = cellElement.getAttribute('data-cell');
            if (!dataCell) return false;

            // Extraer la letra de columna del atributo data-cell
            const match = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
            if (match) {
                const keyCoords = match[1].replace(/[()]/g, ''); 
                return keyCoords.split(',')[0] === colLetter;
            }
            return false;
        });

        if (colIndex !== -1) {
            row.deleteCell(colIndex);
        }
    }

    // Re-renderizar para asegurar que todo esté limpio y actualizado
    render(); 
    return true;
}
```

### FUNCION: setBackgroundColor
```javascript
/**
 * Establece el color de fondo para todas las celdas de una columna dada.
 * @param {string} colLetter La letra de la columna (ej: "A").
 * @param {string} color Código de color CSS (ej: "#ffff00").
 */
function setBackgroundColor(colLetter, color) {
    const bodyRows = document.querySelectorAll('#spreadsheet-grid tbody tr');

    let updatedCount = 0;
    for (const row of bodyRows) {
        // Buscar la celda en esta fila que corresponde a colLetter
        const dataCellsInRow = Array.from(row.children);
        for (const cellElement of dataCellsInRow) {
            if (!cellElement || !cellElement.hasAttribute('contenteditable')) continue;

            const dataCell = cellElement.getAttribute('data-cell');
            if (!dataCell) continue;

            // Verificar si la celda pertenece a la columna seleccionada
            const coordsMatch = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
            if (coordsMatch) {
                const key = coordsMatch[1].replace(/[()]/g, ''); 
                const col = key.split(',')[0];

                if (col === colLetter) {
                    cellElement.style.backgroundColor = color;
                    updatedCount++;
                } else {
                     // Restaurar el fondo si estamos aplicando un nuevo color diferente al blanco predeterminado de la hoja
                     // Esto es crucial para evitar que el color anterior persista incorrectamente si no se limpia en deleteColumn/clearColumnContents.
                    cellElement.style.backgroundColor = ''; 
                }
            }
        }
    }
    return updatedCount;
}
