### FUNCION: clearColumnContents
```javascript
/**
 * Borra el contenido de todas las celdas de una columna dada, actualizando el estado interno.
 * @param {string} colLetter La letra de la columna (ej: "A").
 */
function clearColumnContents(colLetter) {
    let clearedCount = 0;
    const bodyRows = document.querySelectorAll('#spreadsheet-grid tbody tr');

    for (const row of bodyRows) {
        // Iterar sobre todas las celdas de la fila para encontrar la clave y borrarla del estado.cells
        const cellsInRow = Array.from(row.children);
        for (const cellElement of cellsInRow) {
            if (!cellElement || !cellElement.hasAttribute('contenteditable')) continue;

            const dataCell = cellElement.getAttribute('data-cell');
            if (!dataCell) continue;

            const coordsMatch = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
            if (coordsMatch) {
                const key = coordsMatch[1].replace(/[()]/g, ''); 
                const col = key.split(',')[0];

                if (col === colLetter) {
                    delete estado.cells[key];
                    clearedCount++;
                }
            }
        }
    }
    // El render() llamado después en conectar() se encargará de borrar el contenido del DOM.
    return clearedCount;
}
