### FUNCION: selectColumn
```javascript
/**
 * Selecciona una columna, actualizando la UI y preparando para acciones de columna.
 * @param {string} colLetter La letra de la columna seleccionada.
 */
function selectColumn(colLetter) {
    // 1. Deseleccionar todas las columnas primero (limpieza visual)
    document.querySelectorAll('#spreadsheet-grid thead th').forEach(th => {
        th.style.backgroundColor = ''; // Resetear color de fondo
        th.classList.remove('selected-column');
    });

    // 2. Seleccionar la columna activa
    const selectedHeader = document.querySelector(`#spreadsheet-grid thead th:nth-child(${colLetter.charCodeAt(0) - 'A'.charCodeAt(0) + 2})`);
    if (selectedHeader && colLetter === selectedHeader.textContent.trim()) {
        // Aplicar estilo visual de selección
        selectedHeader.style.backgroundColor = '#e6f7ff'; // Light blue background for selection
        selectedHeader.classList.add('selected-column');

        // 3. Mostrar un mensaje o estado (opcional, pero útil para debug/UX)
        console.log(`Columna ${colLetter} seleccionada.`);
    } else {
         console.warn(`No se pudo seleccionar la columna ${colLetter}.`);
    }
}
