### FUNCION: deleteColumn
```js
function deleteColumn() {
    const letter = estado.selectedColumnLetter;
    if (!letter) return;

    if (!confirm(`¿Está seguro de que desea eliminar la columna ${letter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Limpiar el estado de las celdas eliminadas
    const keysToDelete = [];
    document.querySelectorAll(`[data-cell^="${letter}"]`).forEach(element => {
        const key = element.getAttribute('data-cell').replace(/[()]/g, '');
        keysToDelete.push(key);
    });

    keysToDelete.forEach(key => delete estado.cells[key]);

    // 2. Eliminar los elementos del DOM (Headers y Cells)
    const headers = document.querySelectorAll(`.col-header[data-column-letter="${letter}"]`);
    headers.forEach(header => header.remove());

    document.querySelectorAll(`[data-cell^="${letter}"]`).forEach(tdElement => {
        tdElement.remove();
    });

    // 3. Resetear la selección y actualizar la vista
    estado.selectedColumnLetter = null;
    document.getElementById('selected-column-indicator').textContent = 'Ninguna';
    const opControls = document.querySelector('.column-operations');
    if (opControls) {
        opControls.style.display = 'none';
    }

    // Re-renderizar para asegurar que todo esté limpio
    guardar();
    render();
}
```

