function deleteColumn() {
    if (!estado.selectedColumn) return false;
    const col = estado.selectedColumn;

    let keysToDelete = [];
    // Recolectar todas las claves que pertenecen a la columna seleccionada
    for (const key in estado.cells) {
        if (key.startsWith(col + ',')) {
            keysToDelete.push(key);
        }
    }

    if (keysToDelete.length === 0) {
        alert(`La columna ${col} está vacía y no se puede borrar.`);
        return false;
    }

    // Borrar datos de estado
    keysToDelete.forEach(key => delete estado.cells[key]);

    // Limpiar el estilo de la columna eliminada
    delete estado.columnStyles[col]; 

    estado.selectedColumn = null; // Deseleccionar después de borrar
    guardar();
    render();
    return true;
}
