```js
function deleteColumn() {
    const selectedCol = estado.selectedColumn;
    if (!selectedCol) return false;

    // 1. Eliminar el encabezado de la columna (ej: <th>A</th>)
    const headerElement = document.querySelector('.col-header[data-column-letter="' + selectedCol + '"]');
    if (headerElement) {
        headerElement.remove();
    }

    // 2. Eliminar todas las celdas de datos correspondientes en el tbody
    const cellsToDelete = document.querySelectorAll('#spreadsheet-grid td[data-cell*="(' + selectedCol + ',"]');
    cellsToDelete.forEach(td => td.remove());

    // 3. Limpiar estado y selección
    estado.selectedColumn = null;
    guardar();
    render(); // Redibujar para asegurar que el estado se refleja en la UI si hay cambios de estructura (aunque aquí solo elimina elementos).
    return true;
}
```

### FUNCION: clearColumnContent
```js
function clearColumnContent() {
    const selectedCol = estado.selectedColumn;
    if (!selectedCol) return false;

    let clearedCount = 0;
    // Iterar sobre todas las filas para encontrar y limpiar las celdas de la columna seleccionada
    document.querySelectorAll('#spreadsheet-grid td[data-cell*="(' + selectedCol + ',"]').forEach(td => {
        const key = `${selectedCol}, ${obtenerCoordenadas(td).row}`;
        if (estado.cells[key] !== undefined && estado.cells[key] !== null) {
            // Limpiar el contenido visualmente
            td.textContent = '';
            // Eliminar del estado interno
            delete estado.cells[key];
            clearedCount++;
        }
    });

    guardar();
    render(); // Redibujar para reflejar los vacíos en la UI
    return clearedCount > 0;
}
```

