body {
    font-family: Arial, sans-serif;
    padding: 20px;
}

#app-title {
    margin-bottom: 20px;
    color: #333;
}

/* --- Controles de Color y Columna --- */
.controls-group {
    display: flex;
    gap: 10px;
    align-items: center;
    padding: 10px;
    border: 1px solid #ccc;
    border-radius: 5px;
    margin-bottom: 20px;
}

.dropdown {
    display: flex;
    gap: 10px;
    align-items: center;
    padding: 8px;
    border: 1px solid #ccc;
    background-color: #f9f9f9;
    border-radius: 3px;
}

.hidden {
    display: none !important;
}

button {
    padding: 8px 15px;
    cursor: pointer;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 4px;
    transition: background-color 0.2s;
}

button:hover:not(:disabled) {
    background-color: #0056b3;
}

button:disabled {
    background-color: #cccccc;
    cursor: not-allowed;
}

input[type="color"] {
    width: 50px;
    height: 30px;
    padding: 0;
    border: none;
    background-color: transparent;
    cursor: pointer;
}

/* --- Estructura de la Tabla --- */
#spreadsheet-grid {
    border-collapse: collapse;
    width: 100%;
    table-layout: fixed;
}

#spreadsheet-grid th, #spreadsheet-grid td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
    min-width: 50px; /* Asegura que las celdas tengan un tamaño mínimo */
}

/* Estilo de la esquina superior izquierda */
.corner-cell {
    background-color: #eee;
    border: none;
    padding: 0;
}

/* Encabezado de Fila (Números) */
.row-header {
    background-color: #f2f2f2;
    font-weight: bold;
    width: 40px; /* Ancho fijo para los números de fila */
    text-align: center;
}

/* Encabezado de Columna (Letras) - Hacen que sean clickables y seleccionables */
.col-header {
    background-color: #e9ecef;
    font-weight: bold;
    cursor: pointer;
    text-align: center;
    user-select: none; /* Previene la selección de texto al hacer clic rápido */
}

/* Estado seleccionado para una columna */
.col-header.selected {
    background-color: #cce5ff !important; /* Azul claro */
    box-shadow: inset 0 -2px 0 #007bff;
}

/* Estilo de las celdas editables */
[contenteditable="true"]:focus {
    outline: 2px solid #007bff;
    background-color: #fff !important; /* Asegura que el foco sea visible */
}
