function selectColumn(colLetter) {
    // Deseleccionar todos los encabezados de columna
    document.querySelectorAll('.col-header').forEach(el => el.classList.remove('selected'));

    // Seleccionar el encabezado dado
    const headerElement = document.querySelector(`.select-able[data-col="${colLetter}"]`);
    if (headerElement) {
        headerElement.classList.add('selected');
        estado.selectedColumn = colLetter; // Almacenar en estado global si fuera necesario, aunque usaremos el DOM para la UI
        updateColumnControls(colLetter);
    } else {
        estado.selectedColumn = null;
        updateColumnControls(null);
    }
}
