```js
function deleteSelectedColumn() {
    const colLetter = estado.selectedColumn;
    if (!colLetter || !confirm(`¿Está seguro de que desea borrar la columna ${colLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Actualizar el estado: Eliminar todas las entradas de esta columna
    let keysToDelete = [];
    for (const key in estado.cells) {
        if (key.startsWith(`${colLetter},`)) {
            keysToDelete.push(key);
        }
    }

    keysToDelete.forEach(key => delete estado.cells[key]);

    // 2. Actualizar el DOM: Eliminar la columna de los encabezados y las celdas
    const headerCells = document.querySelectorAll('.col-header');
    let colIndex = -1; // Índice del TH en elad row (empezando desde A=0)
    Array.from(headerCells).forEach((th, index) => {
        if (th.dataset.col === colLetter) {
            colIndex = index;
        }
    });

    if (colIndex === -1) return; // No se encontró la columna en el encabezado

    // Eliminar el TH del encabezado
    const headerRow = document.querySelector('.column-header-row');
    headerRow.deleteCell(colIndex + 1); // +1 porque el primer TH es para el índice de fila

    // Iterar sobre todas las filas del cuerpo y eliminar la celda correspondiente
    document.querySelectorAll('#spreadsheet-grid tbody tr').forEach(row => {
        // El TD a borrar está en la posición colIndex + 1 (después del th.row-header)
        const cellToRemove = row.children[colIndex + 1];
        if (cellToRemove) {
            row.removeChild(cellToRemove);
        }
    });

    // 3. Limpiar estado y UI
    estado.selectedColumn = null;
    guardar();
    render();
    updateColumnControls(null);
}
```

