function clearSelectedColumnContent() {
    if (!estado.selectedColumn) return;
    const columnLetter = estado.selectedColumn;
    let cellsClearedCount = 0;

    // Iterar sobre todas las filas (tr en tbody)
    document.querySelectorAll('#spreadsheet-grid tbody tr').forEach(row => {
        // Buscar el TD correspondiente a la columna seleccionada
        const cellElement = row.querySelector(`[data-cell*='(${columnLetter},']`);

        if (cellElement) {
            const dataCell = cellElement.getAttribute('data-cell');
            const keyMatch = dataCell ? dataCell.match(/([A-Z]+), (\d+)/) : null;
            if (!keyMatch) return;

            const rowNumber = keyMatch[2];
            const key = `${columnLetter}, ${rowNumber}`;

            // 1. Limpiar el estado
            estado.cells[key] = '';

            // 2. Actualizar la celda en el DOM y guardar/render (simulando un focusout)
            cellElement.textContent = '';
            cellsClearedCount++;
        }
    });

    guardar();
    render();
}
