function initializeColumnControls() {
    const headerRow = document.querySelector('#spreadsheet-grid thead tr');
    if (!headerRow) return;

    // Iterar sobre los TH que contienen las letras de columna (A, B, C...)
    let colIndex = 1; // Empezamos en el índice 1 porque el 0 es la esquina vacía/para título
    const allHeaders = headerRow.querySelectorAll('th');

    for(let i = 1; i < allHeaders.length; i++) {
        const headerTh = allHeaders[i];
        const letter = headerTh.textContent.trim();

        // Crear el contenedor de acciones si no existe o necesita ser modificado
        let actionsContainer = document.getElementById(`actions-${letter}`);
        if (!actionsContainer) {
            actionsContainer = document.createElement('div');
            actionsContainer.id = `actions-${letter}`;
            actionsContainer.className = 'column-controls column-actions';
            headerTh.appendChild(actionsContainer);
        }

        // Botón de Selección (se puede eliminar si solo se usa el clic en la letra, pero es más robusto)
        const selectButton = document.createElement('button');
        selectButton.textContent = `Seleccionar ${letter}`;
        selectButton.className = 'select-col';
        selectButton.onclick = () => selectColumn(letter);

        // Botón de Vaciar
        const clearButton = document.createElement('button');
        clearButton.textContent = 'Vaciar Columna';
        clearButton.id = `clear-${letter}`;
        clearButton.className = 'action-btn delete';
        clearButton.onclick = () => {
            if (confirm(`¿Está seguro de vaciar todo el contenido de la columna ${letter}?`)) {
                clearSelectedColumnContent();
            }
        };

        // Contenedor para Color y Borrar
        const colorGroup = document.createElement('div');
        colorGroup.className = 'action-group';

        // Botón de Color
        const colorButton = document.createElement('button');
        colorButton.textContent = '🎨 Fondo';
        colorButton.id = `color-${letter}`;
        colorButton.className = 'action-btn';
        colorButton.onclick = () => {
             document.getElementById(`actions-${letter}`).querySelector('.select-col').click(); // Asegurar selección primero
            document.getElementById('toggle-color-picker').click();
        };

        // Botón de Borrar Columna (Delete)
        const deleteButton = document.createElement('button');
        deleteButton.textContent = '🗑️ Eliminar';
        deleteButton.id = `delete-${letter}`;
        deleteButton.className = 'action-btn danger';
        deleteButton.onclick = () => {
            if (confirm(`⚠️ ¿Está seguro de eliminar completamente la columna ${letter}? Esta acción es irreversible.`)) {
                deleteSelectedColumn();
            }
        };

        // Agregar botones al contenedor de acciones
        actionsContainer.innerHTML = ''; // Limpiar si ya se había añadido algo por defecto
        actionsContainer.appendChild(selectButton);
        actionsContainer.appendChild(clearButton);
        actionsContainer.appendChild(colorGroup);
        colorGroup.appendChild(colorButton);
        colorGroup.appendChild(deleteButton);

        // Manejo de clic en la letra (alternativa al botón de selección)
        headerTh.style.cursor = 'pointer';
        headerTh.addEventListener('click', () => selectColumn(letter));

    }
}
