### FUNCION: seleccionarFila
```javascript
/**
 * Selecciona una fila específica, actualiza el estado y habilita/deshabilita los controles de acción.
 * @param {HTMLElement} rowElement El elemento TR que contiene la fila seleccionada.
 */
function seleccionarFila(rowElement) {
    // 1. Deseleccionar todas las filas primero (limpieza visual y lógica)
    document.querySelectorAll('#spreadsheet-grid .row-header').forEach(header => {
        header.classList.remove('selected');
        header.style.backgroundColor = '';
    });

    // 2. Seleccionar la fila actual
    rowElement.querySelector('.row-header').classList.add('selected');

    const rowNumber = rowElement.dataset.row;
    if (!rowNumber) return;

    // 3. Actualizar el estado global de la selección
    estado.selectedRowId = rowNumber;

    // 4. Habilitar/Deshabilitar controles basados en si hay una fila seleccionada
    const controlsDisabled = !rowNumber;
    document.getElementById('delete-row-btn').disabled = controlsDisabled;
    document.getElementById('colorize-row-btn').disabled = controlsDisabled;
    document.getElementById('clear-row-content-btn').disabled = controlsDisabled;
}
```

