/**
 * Borra completamente la fila seleccionada, actualizando el estado y la vista.
 */
function borrarFilaSeleccionada() {
    const rowToBorr = document.querySelector('#spreadsheet-grid tbody tr[data-row="' + (estado.selectedRowId || '') + '"]');

    if (!rowToBorr) return;

    // 1. Eliminar la fila del DOM
    rowToBorr.remove();

    // 2. Limpiar el estado de selección y datos
    const rowNumber = estado.selectedRowId;
    estado.selectedRowId = null;

    // Borrar todos los datos asociados a esta fila en el estado (A, N) hasta (J, N)
    for (let colCode = 'A'; colCode <= 'J'; colCode++) { // Asumiendo que solo manejamos A-J por ahora
        const key = `${colCode}, ${rowNumber}`;
        delete estado.cells[key];
    }

    // 3. Limpiar la UI y redibujar (aunque no haya cambios visibles, es buena práctica)
    seleccionarFila(null); // Resetea los botones y clases
    guardar();
    render();
}
