function handleRowActions(event, selectedRowElement) {
    if (!selectedRowElement) return;

    const target = event.target;

    // 1. Borrar Fila (Delete Row)
    if (target.id === 'delete-row-btn') {
        const rowToDelete = selectedRowElement.parentNode; // El TR completo
        const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
        let rowIndexToRemove = -1;

        // Encontrar el índice de la fila a borrar (basado en los datos visibles)
        for(let i = 0; i < rows.length; i++) {
            if (rows[i] === selectedRowElement.parentNode) {
                rowIndexToRemove = i;
                break;
            }
        }

        if (rowIndexToRemove !== -1) {
            // Lógica de eliminación en el DOM (la fila completa)
            rowToDelete.remove();

            // Limpiar la selección visual y cualquier estado asociado
            document.querySelectorAll('#spreadsheet-grid tbody tr').forEach(r => r.classList.remove('selected-row'));
        }
    } 

    // 2. Cambiar Color de Fondo (Colorize Row)
    else if (target.id === 'colorize-row-btn') {
        const color = document.getElementById('color-picker').value;
        if (!color) return;

        // Obtener todos los TD dentro de la fila seleccionada, excluyendo el header de fila
        const cellsToColorize = selectedRowElement.querySelectorAll('td');

        cellsToColorize.forEach(cell => {
            // Aplicar directamente el estilo CSS al elemento DOM para asegurar que se vea
            cell.style.backgroundColor = color; 
            // Si quieres guardar este color en estado, necesitarías una lógica más compleja de gestión de estilos.
        });
    } 

    // 3. Borrar Contenido (Clear Row Content)
    else if (target.id === 'clear-row-content-btn') {
        const cellsToClear = selectedRowElement.querySelectorAll('td');

        cellsToClear.forEach(cell => {
            // Limpiar el contenido visible del DOM
            cell.textContent = ''; 
            // Resetear estilos de fondo (para que no queden restos)
            cell.style.backgroundColor = ''; 
        });
    }
}
