```javascript
/**
 * Vacía el contenido de todas las celdas en una fila dada su índice de fila (1-based).
 * @param {number} rowIndex El número de la fila a vaciar.
 */
function clearRowContent(rowIndex) {
    if (!rowIndex || isNaN(parseInt(rowIndex))) return false;

    let clearedCount = 0;
    // Iteramos por las primeras 26 columnas (A-Z) para cubrir un rango típico de hoja de cálculo
    for (let i = 1; i <= 26; i++) { 
        const colCode = String.fromCharCode(64 + i); // Get column letter A, B, C...
        const key = `${colCode}, ${rowIndex}`;

        if (estado.cells[key] !== undefined) {
            delete estado.cells[key];
            clearedCount++;
        }
    }

    // Guardar el nuevo estado y redibujar la vista para reflejar los cambios de vacío.
    guardar(); 
    render();
    return clearedCount;
}
