/**
 * Borra el contenido de todas las celdas de una fila específica y actualiza el estado interno.
 * @param {HTMLElement} rowElement El elemento TR que contiene los TD a limpiar.
 */
function clearRowContent(rowElement) {
    if (!rowElement || !rowElement.hasAttribute('data-row')) return;

    // Iterar sobre todos los hijos de la fila (los TD).
    const cellElements = Array.from(rowElement.children).filter(el => el.tagName === 'TD');

    let clearedCount = 0;

    cellElements.forEach(td => {
        const dataCell = td.getAttribute('data-cell');
        if (!dataCell) return;

        // Extraer clave: "A, 3" (Columna, Espacio, Número)
        const coordsMatch = dataCell.match(/(\([A-Z]\, [0-9]+\))/);
        if (coordsMatch) {
            const key = coordsMatch[1].replace(/[()]/g, ''); // e.g., "A, 3"

            // Limpiar el estado para esta celda
            estado.cells[key] = '';
            clearedCount++;
        }
    });

    if (clearedCount > 0) {
        guardar();
        render();
    }
}
