/* Estilos para el contenedor de controles */
.controls-group {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
    padding: 10px;
    border: 1px solid #ccc;
    background-color: #f9f9f9;
}

.controls-group button, .controls-group select {
    padding: 8px 15px;
    cursor: pointer;
    border: none;
    background-color: #007bff;
    color: white;
    border-radius: 4px;
}

.controls-group button:hover, .controls-group select:hover {
    opacity: 0.9;
}

/* Estilos de la grilla */
#spreadsheet-grid {
    width: 90%;
    border-collapse: collapse;
    margin: 20px auto;
    table-layout: fixed;
}

#spreadsheet-grid th, #spreadsheet-grid td {
    border: 1px solid #ddd;
    padding: 8px;
    min-width: 50px; /* Asegurar un ancho base para las celdas */
    height: 30px;
    box-sizing: border-box;
}

/* Estilo de la esquina superior izquierda */
.corner-header {
    background-color: #eee;
    border: 1px solid #ddd;
    padding: 0;
    width: 50px; /* Debe coincidir con el ancho de los encabezados de fila */
}

/* Encabezado de columna (A, B, C...) */
.column-letter {
    background-color: #f2f2f2;
    font-weight: bold;
    text-align: center;
    cursor: pointer; /* Indica que se puede hacer clic para acciones */
}

/* Encabezado de fila (1, 2, 3...) */
.row-header {
    background-color: #f2f2f2;
    font-weight: bold;
    text-align: center;
    cursor: pointer; /* Indica que se puede hacer clic para acciones */
}

/* Estilos de las celdas editables */
[contenteditable="true"] {
    outline: none; /* Eliminar el borde azul por defecto del navegador al editar */
    cursor: text;
}

/* Clase CSS para ocultar elementos (aplicada a tr, th, td) */
.hidden-element {
    display: none !important;
}

/* Estilos de colorización */
.colored-row {
    background-color: #fff3cd !important; /* Color de ejemplo por defecto */
}

/* Dropdown para el selector de color */
.dropdown {
    position: absolute;
    z-index: 10;
    border: 1px solid #ccc;
    padding: 10px;
    background-color: white;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.hidden {
    display: none !important;
}
