```js
function obtenerCoordenadas(element) {
    const rect = element.getBoundingClientRect();
    const gridRect = document.getElementById('spreadsheet-grid').getBoundingClientRect();

    // Calcular coordenadas relativas al inicio de la cuadrícula visible
    const leftOffset = rect.left - gridRect.left;
    const topOffset = rect.top - gridRect.top;

    // Determinar el índice de columna (A=0, B=1, ...) y fila (1-based)
    let colIndex = Math.floor(leftOffset / 100); // Asumiendo que cada celda es aproximadamente 100px ancha en su contenedor
    let rowIndex = Math.floor(topOffset / 40);   // Asumiendo que cada fila es aproximadamente 40px alta

    return { colIndex: colIndex, rowIndex: rowIndex + 1 };
}
