            }

            const letter = String.fromCharCode(65 + i);
            const cellValue = getCellValue(`${letter}${r}`);
            let content = cellValue !== null ? cellValue : '';

            // Aplicar clase hidden a la celda completa si es necesario (aunque el contenedor de col/fila ya debería manejarlo)
            let cellClass = 'spreadsheet-cell';

            rowHtml += `<div class="${cellClass}" data-col="${i}" data-row="${r}">`;
            rowHtml += `<span contenteditable="true" class="content">${content}</span>`;
            rowHtml += `</div>`;
        }

        // Si no se saltó ninguna columna (porque la primera columna es de la esquina)
        if (!estado.hiddenColumns.has('A')) { 
             rowHtml += '</div>'; // Cierre del div row-header/grid-body, si lo necesitas para estructura
        } else {
            // Ajuste estructural: El grid body debe contener los divs de las filas visibles.
             htmlContent += `<div class="spreadsheet-row" data-row="${r}">`;
             let cellHtml = '';
             for (let i = 0; i < 26; i++) {
                 if (!estado.hiddenColumns.has(String.fromCharCode(65 + i))) {
                     const letter = String.fromCharCode(65 + i);
                     const cellValue = getCellValue(`${letter}${r}`);
                     let content = cellValue !== null ? cellValue : '';
                     cellHtml += `<div class="spreadsheet-cell" data-col="${i}" data-row="${r}">`;
                     cellHtml += `<span contenteditable="true" class="content">${content}</span>`;
                     cellHtml += `</div>`;
                 }
             }
             htmlContent += cellHtml;
        }

    }

    // Nota: La renderización de la cuadrícula es compleja debido a que los headers y el grid body deben interactuar. 
    // Simplificando para asegurar la visibilidad/ocultamiento del contenido principal:
    gridBody = '';
    for (let r = 1; r <= 20; r++) { 
        if (estado.hiddenRows.has(r)) continue;

        let rowHtml = '<div class="spreadsheet-row" data-row="' + r + '">';

        // Columna A siempre va primero en el contenido visible si no hay headers de columna/fila separados
        let firstCellContent = '';
         if (!estado.hiddenColumns.has('A')) {
            const cellValue = getCellValue(`A${r}`);
            let content = cellValue !== null ? cellValue : '';
            firstCellContent += `<div class="spreadsheet-cell" data-col="0" data-row="${r}">`;
            firstCellContent += `<span contenteditable="true" class="content">${content}</span>`;
            firstCellContent += `</div>`;
         }

        for (let i = 1; i < 26; i++) { // Empieza desde la columna B (índice 1)
            const letter = String.fromCharCode(65 + i);
            if (estado.hiddenColumns.has(letter)) continue;

            const cellValue = getCellValue(`${letter}${r}`);
            let content = cellValue !== null ? cellValue : '';

            rowHtml += `<div class="spreadsheet-cell" data-col="${i}" data-row="${r}">`;
            rowHtml += `<span contenteditable="true" class="content">${content}</span>`;
            rowHtml += `</div>`;
        }
        // Reemplazando la complejidad con un enfoque más directo: 
    }

    // Volver a generar el cuerpo usando la lógica de columnas/filas visibles para asegurar que los elementos se anidan correctamente.
     let finalGridBody = '';
     for (let r = 1; r <= 20; r++) {
         if (estado.hiddenRows.has(r)) continue;

         let rowContentHtml = '<div class="spreadsheet-row" data-row="' + r + '">';
         // Aquí asumimos que el contenido del grid debe ser generado para todas las celdas visibles. 
         // Dado que la estructura de render es compleja, solo nos enfocamos en aplicar la clase "hidden" a los contenedores principales.

         let cellContents = '';
         for (let i = 0; i < 26; i++) {
             if (estado.hiddenColumns.has(String.fromCharCode(65 + i))) continue;

             const letter = String.fromCharCode(65 + i);
             const cellValue = getCellValue(`${letter}${r}`);
             let content = cellValue !== null ? cellValue : '';

             cellContents += `<div class="spreadsheet-cell" data-col="${i}" data-row="${r}">`;
             cellContents += `<span contenteditable="true" class="content">${content}</span>`;
             cellContents += `</div>`;
         }

         finalGridBody += rowContentHtml + cellContents;

     }


    // Actualizar el DOM con los headers y el cuerpo de la cuadrícula visible.
    document.querySelector('.corner-header').innerHTML = ''; // Limpieza

    let gridHtml = `
        <div class="spreadsheet-grid">
            ${colHeadersHtml}
            <div class="grid-body">${finalGridBody}</div>
        </div>`;

    // Nota: Debido a la complejidad de manipular el DOM con HTML generado y mantener los elementos interactivos, 
    // nos aseguramos que al menos las clases de visibilidad se apliquen correctamente.
    document.getElementById('spreadsheet-grid').innerHTML = gridHtml;


    // Reaplicar listeners para cualquier nuevo elemento editable (aunque esto es más complejo en la práctica)
    attachContentEditableListeners();
