function toggleColumnVisibility(colLetter) {
    const grid = document.getElementById('spreadsheet-grid');
    if (!grid) return;

    // 1. Ocultar/Mostrar encabezado de columna (A, B, C...) en THEAD
    let colHeader = grid.querySelector(`.column-letter[data-col="${colLetter}"]`);
    const isHidden = colHeader ? colHeader.classList.contains('hidden-element') : false;

    if (colHeader) {
        colHeader.classList.toggle('hidden-element');
    }

    // 2. Ocultar/Mostrar todas las celdas de datos (TD) en el BODY
    const dataCells = grid.querySelectorAll(`[data-cell^="${colLetter}"]`);
    dataCells.forEach(cell => {
        cell.classList.toggle('hidden-element');
    });

    // 3. Ocultar/Mostrar los encabezados de fila (TH) en la cabecera del body, si aplica
    const rowHeaders = grid.querySelectorAll('.row-header[data-col^="'+colLetter+'"]');
     rowHeaders.forEach(header => {
        header.classList.toggle('hidden-element');
    });
}
