### FUNCION: handleHeaderClick
```javascript
function handleHeaderClick(event) {
    const target = event.target;
    if (!target) return;

    // Si es un encabezado de columna (A, B, C...)
    if (target.classList.contains('column-letter')) {
        const colLetter = target.getAttribute('data-col');
        toggleColumnVisibility(colLetter);
        return;
    }

    // Si es un encabezado de fila (1, 2, 3...)
    if (target.classList.contains('row-header')) {
        const rowIndex = target.getAttribute('data-row');
        toggleRowVisibility(rowIndex);
    }
}
